-- =============================================================================
-- Expiration / Compliance Tracker
-- PostgreSQL. Ejecutar una sola vez (es idempotente: se puede volver a correr).
-- =============================================================================

-- 1) Tabla de registros (privados por usuario: cada fila pertenece a "UserId")
CREATE TABLE IF NOT EXISTS "ComplianceItems" (
    "Id"               integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "UserId"           integer                  NOT NULL,
    "CompanyId"        integer                  NOT NULL,
    "Description"      character varying(500)   NOT NULL,
    "RegistrationDate" date                     NOT NULL,
    "ExpirationDate"   date                     NOT NULL,
    "CreatedAt"        timestamp with time zone NOT NULL DEFAULT NOW(),
    "UpdatedAt"        timestamp with time zone NULL,
    "IsDelete"         boolean                  NULL DEFAULT false,
    "DeleteAt"         timestamp with time zone NULL,
    CONSTRAINT "PK_ComplianceItems" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ComplianceItems_Users" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id"),
    CONSTRAINT "FK_ComplianceItems_Companies" FOREIGN KEY ("CompanyId") REFERENCES "Companies" ("Id"),
    CONSTRAINT "CK_ComplianceItems_Dates" CHECK ("ExpirationDate" >= "RegistrationDate")
);

-- Índice para la consulta principal: registros del usuario ordenados por vencimiento
CREATE INDEX IF NOT EXISTS "IX_ComplianceItems_UserId_ExpirationDate"
    ON "ComplianceItems" ("UserId", "ExpirationDate");

-- 2) Menú (queda disponible en "Assign Menus" para asignarlo a los tipos de usuario)
INSERT INTO "Menus" ("Title", "Route", "Icon", "SortOrder", "IsActive", "CreatedAt", "ParentId", "IsSystem")
SELECT 'Compliance Tracker',
       '/compliance-tracker',
       'ShieldCheck',
       COALESCE((SELECT MAX("SortOrder") FROM "Menus"), 0) + 1,
       true,
       NOW(),
       NULL,
       false
WHERE NOT EXISTS (SELECT 1 FROM "Menus" WHERE "Route" = '/compliance-tracker');

